function filterAndCleanElementTexts(texts: string[]): string[]{
    return [...new Set( //Loại bỏ các phần tử trùng lặp
        //[...] chuyển Set thành mảng
        texts
            .map(text => text.trim()) //Loại bỏ khoảng trắng ở đầu và cuối chuỗi
            .filter(text => text.length > 0)//Bỏ các chuỗi rỗng
            .map(text => text.toUpperCase())//Chuyển tất cả các chuỗi thành chữ hoa
    )];
}
//console.log(filterAndCleanElementTexts([" apple ", "banana", "", "APPLE"]));

type TestCaseUser = {
  username: string;
  email: string;
  age: number;
  role: 'admin' | 'user' | 'guest';
};

const testUsers: TestCaseUser[] = [
  {
    username: "admin01",
    email: "admin01@example.com",
    age: 25,
    role: "admin"
  },
  {
    username: "user01",
    email: "user01@example.com",
    age: 20,
    role: "user"
  },
  {
    username: "admin02",
    email: "admin02@example.com",
    age: 17,
    role: "admin"
  },
  {
    username: "guest01",
    email: "guest01@example.com",
    age: 30,
    role: "guest"
  }
];

function getValidAdminUsers(users: TestCaseUser[]): string[] { 
    //Hàm này nhận vào một mảng các đối tượng người dùng (users) và trả về một mảng các tên người dùng (username) của những người dùng hợp lệ (valid admin users)
  return users 
    .filter(user => user.role === "admin" && user.age >= 18)// Lọc ra những người dùng có role là "admin" và tuổi >= 18
    .map(user => user.username);// Lấy ra danh sách username của những người dùng hợp lệ
}
const validAdmins = getValidAdminUsers(testUsers);// Gọi hàm và lưu kết quả vào biến validAdmins
//console.log(validAdmins);

type HeaderPair = [string, string];//Định nghĩa kiểu dữ liệu HeaderPair là một mảng gồm hai phần tử, cả hai đều là chuỗi (string)

function convertHeadersToObject(
  headers: HeaderPair[]
): Record<string, string> { //Record<string, string> đại diện cho một đối tượng có các khóa là chuỗi (string) và các giá trị cũng là chuỗi (string). 
    //Nó được sử dụng để định nghĩa một đối tượng mà bạn biết trước rằng các khóa sẽ là chuỗi và các giá trị tương ứng cũng sẽ là chuỗi.
  return headers.reduce<Record<string, string>>((result, [key, value]) => { 
    //Sử dụng reduce() để chuyển đổi mảng headers thành một đối tượng
    result[key] = value; //Gán giá trị value cho khóa key trong đối tượng result
    return result;
  }, {}) //Khởi tạo result là một đối tượng rỗng {} để bắt đầu quá trình giảm (reduce)
};
const headers: HeaderPair[] = [
  ["Authorization", "Bearer token123"],
  ["Content-Type", "application/json"]
];

const headerObject = convertHeadersToObject(headers);

console.log(headerObject);
